ENABLE TRIGGER HC.trgRecalculateRunCounts ON HC.Event;
-- The reconciliation: what the trigger would have done per statement.
UPDATE HC.Event SET EventStartDatetimeIndexed = CONVERT(datetime2, EventStartDatetime)
WHERE KennelId = @kennelId AND EventSource = N'Import chihhh.org.uk';
EXEC HC6.nonApi_updateRunNumbers @kennelId = @kennelId;
COMMIT TRANSACTION;
SELECT name, is_disabled FROM sys.triggers WHERE parent_id = OBJECT_ID('HC.Event');
SELECT COUNT(*) AS runs, SUM(CASE WHEN OfficialTrailGzip IS NOT NULL THEN 1 ELSE 0 END) AS withTrail,
       MIN(EventNumber) AS firstNo, MAX(EventNumber) AS lastNo,
       SUM(CASE WHEN EventNumber <> AbsoluteEventNumber THEN 1 ELSE 0 END) AS numberMismatches
FROM HC.Event WHERE KennelId = @kennelId AND deleted = 0;
